656	  /** Opens the workflow's configured run root no-follow for one operation. An unusable root is a 503, never an empty list. */
657	  private async withRunsRoot<T>(scope: Scope, operation: (root: FileHandle) => Promise<T>): Promise<T> {
658	    let root: FileHandle
659	    try {
660	      root = await fs.open(scope.workflow.runs_root, DIRECTORY_FLAGS)
661	    } catch (error) {
662	      const code = errno(error)
663	      const reason = code === 'ENOENT' ? 'does not exist' : code === 'EACCES' || code === 'EPERM' ? 'is not readable' : 'is not a directory (symbolic links are never followed)'
664	      if (!isMissing(error) && code !== 'EACCES' && code !== 'EPERM') throw error
665	      throw new ProjectApiError(503, 'RUNS_ROOT_UNAVAILABLE', `The configured run storage for this workflow ${reason}. Check the registry configuration.`)
666	    }
667	    try {
668	      return await operation(root)
669	    } finally {
670	      await root.close()
671	    }
672	  }
673	
674	  /** Every run under the workflow root, newest first. Legacy directories without a supported export are skipped with a warning. */
675	  async listRuns(scope: Scope): Promise<RunSummary[]> {
676	    return this.withRunsRoot(scope, async root => {
677	      const names = (await fs.readdir(at(root), { withFileTypes: true }))
678	        .filter(dirent => dirent.isDirectory() && ID_PATTERN.test(dirent.name)).map(dirent => dirent.name).sort()
679	      const summaries: RunSummary[] = []
680	      const seen = new Set<string>()
681	      for (const name of names) {
682	        const directory = await openDirectory(root, name)
683	        if (!directory) continue
684	        try {
685	          const state = await readBounded(directory, ['run-state.json'], this.options.exportByteLimit)
686	          if (state === null) {
687	            if (await readBounded(directory, ['plan.json'], this.options.exportByteLimit) !== null) {
688	              this.options.warn?.('Skipping run directory without a supported run-state.json export; explicit import is required', { project_id: scope.project.project_id, workflow_id: scope.workflow.workflow_id, run: name })
689	            }
690	            continue
691	          }
692	          const run = await this.projectRun(scope, name, directory, state)
693	          if (seen.has(run.detail.summary.run_id)) throw invalidRun(name, 'duplicate run ID within the workflow')
694	          seen.add(run.detail.summary.run_id)
695	          summaries.push(run.detail.summary)
696	        } finally {
697	          await directory.close()
698	        }
699	      }
700	      return summaries.sort(compareRuns)
701	    })
702	  }
703	
704	  async loadRun(scope: Scope, runId: string): Promise<LoadedRun> {
705	    return this.withRunsRoot(scope, async root => {
706	      const directory = await openDirectory(root, runId)
707	      if (!directory) throw new ProjectApiError(404, 'RUN_NOT_FOUND', 'No run with that ID exists in this workflow.')
708	      try {
709	        const state = await readBounded(directory, ['run-state.json'], this.options.exportByteLimit)
710	        if (state === null) {
711	          if (await readBounded(directory, ['plan.json'], this.options.exportByteLimit) !== null) {
712	            throw new ProjectApiError(404, 'RUN_UNSUPPORTED', 'This run predates the supported state export and needs an explicit import; it is not displayed.')
713	          }
714	          throw new ProjectApiError(404, 'RUN_NOT_FOUND', 'No run with that ID exists in this workflow.')
715	        }
716	        return await this.projectRun(scope, runId, directory, state)
717	      } finally {
718	        await directory.close()
719	      }
720	    })
721	  }
722	
723	  async workerResult(scope: Scope, runId: string, nodeId: string, attempt: number): Promise<WorkerResult> {
724	    const run = await this.loadRun(scope, runId)
725	    const { phase, worker } = parseResultNode(nodeId)
726	    const packet = run.packets.find(candidate => candidate.phase === phase && candidate.node_id === worker && candidate.attempt === attempt)
727	    if (!packet) throw new ProjectApiError(404, 'RESULT_NOT_FOUND', 'No verified result is registered for that node and attempt.')
728	    if (!packet.ok) throw new ProjectApiError(500, 'EVIDENCE_MISMATCH', `The registered verification packet for ${nodeId}/${attempt} cannot be trusted: ${packet.reason}`)
729	    return projectWorkerResult(scope, runId, nodeId, packet)
730	  }

